import os, sys, subprocess, filecmp, difflib, ast
from pathlib import Path

def syntax_check():
    py_files = list(Path(os.environ['TARGET_DIR']).rglob('*.py'))
    for f in py_files:
        try:
            subprocess.check_call([sys.executable, '-m', 'py_compile', str(f)], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        except subprocess.CalledProcessError:
            print(f'Syntax error in {f}')
            sys.exit(1)
    print('Syntax: OK')

def interface_check():
    def get_params(path):
        tree = ast.parse(Path(path).read_text())
        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name == 'run_agent':
                return [a.arg for a in node.args.args]
        return None
    old = get_params(Path(os.environ['ORIGINAL_DIR']) / 'run_buggy.py')
    new = get_params(Path(os.environ['TARGET_DIR']) / 'run_buggy.py')
    assert new == old, f'run_agent parameters changed: {old} -> {new}'
    print('run_agent interface: OK', new)

def diff_summary():
    diff = []
    for root, _, files in os.walk(os.environ['ORIGINAL_DIR']):
        for name in files:
            if name.endswith('.py'):
                orig = Path(root) / name
                rel = orig.relative_to(os.environ['ORIGINAL_DIR'])
                new = Path(os.environ['TARGET_DIR']) / rel
                if new.is_file():
                    if not filecmp.cmp(orig, new, shallow=False):
                        diff.append(f'Files differ: {orig} vs {new}')
                else:
                    diff.append(f'File missing in target: {new}')
    if diff:
        print('\n'.join(diff))
    else:
        print('(no file differences)')

def prompt_safety_check():
    content = (Path(os.environ['TARGET_DIR']) / 'run_buggy.py').read_text()
    give_up_phrases = [
        'unable to determine', 'cannot find', 'give up', 'stop searching',
        'do not proceed with partial', 'information cannot be found',
        'when information cannot'
    ]
    found = [p for p in give_up_phrases if p.lower() in content.lower()]
    if found:
        print(f'WARNING: Found give-up phrases in the program: {found}')
        persist_phrases = [
            'try', 'alternative', 'exhaust', 'persist', 'another approach',
            'use the context', 'after exhausting'
        ]
        persist_found = [p for p in persist_phrases if p.lower() in content.lower()]
        if not persist_found:
            print('ERROR: No persistence guidance found to balance give-up phrases!')
        else:
            print(f'Persistence phrases found: {persist_found} — review balance carefully')
    else:
        print('Prompt safety check: no problematic give-up phrases detected')

print('=== 1. Syntax check all Python files ===')
syntax_check()
print('\n=== 2. Interface check ===')
interface_check()
print('\n=== 3. Diff summary ===')
diff_summary()
print('\n=== 4. Prompt safety check ===')
prompt_safety_check()
print('\n=== All checks passed ===')
PYEOF

